def transform(grid):
    # Count color frequencies to identify background color
    counts = {}
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    bg_color = None
    max_count = 0
    for color, count in counts.items():
        if count > max_count:
            max_count = count
            bg_color = color

    result = []
    for r_idx, row in enumerate(grid):
        row_list = list(row)
        has_bg = any(cell == bg_color for cell in row_list)
        has_fg = any(cell != bg_color for cell in row_list)

        if has_bg and has_fg:
            # Find foreground segments and their right-side background neighbors
            i = 0
            while i < len(row_list):
                # Skip background
                if row_list[i] == bg_color:
                    i += 1
                    continue

                # Found foreground - mark the right-side background
                j = i
                while j < len(row_list) and row_list[j] != bg_color:
                    j += 1

                # j is now at first background after fg block
                # Convert adjacent background to 1 (offset from end)
                if j < len(row_list):
                    # Determine how many background pixels to convert based on row position
                    offset = (r_idx + len(row_list) - j) % (len(row_list) - j + 1)
                    for k in range(offset):
                        if j + k < len(row_list) and row_list[j + k] == bg_color:
                            row_list[j + (k if k < offset else 0)] = 1
                    i = j
                else:
                    i = j
            result.append(row_list)
        else:
            result.append(list(row))

    return result
